/** Reusable chemical-material paths; source pools supply quantities and processing work. */
public final class BottledChaosReagentRecipes {

    private static final Map<Object, ReagentStep> INPUT_SYNTHESES = new LinkedHashMap<>();
    private static final Map<Object, ReagentStep> OUTPUT_DECOMPOSITIONS = new LinkedHashMap<>();

    static {
        // spotless:off
        // Input paths: follow the recorded inputs upstream, stopping at materials without a synthesis entry.
        addInput(MixerNonCell, AquaRegia, new Object[] { NitricAcid, HydrochloricAcid }, 1);
        addInput(LargeChemicalReactor, AmmoniumChlorideFluid, new Object[] { AmmoniaGas, HydrochloricAcid }, 1);
        addInput(LargeChemicalReactor, HydrochloricAcid, new Object[] { HydrogenGas, ChlorineGas }, 1);
        addInput(LargeChemicalReactor, HydrofluoricAcid, new Object[] { HydrogenGas, FluorineGas }, 9);
        addInput(LargeChemicalReactor, AmmoniaGas, new Object[] { NitrogenGas, HydrogenGas }, 1);
        addInput(LargeChemicalReactor, NitricAcid, new Object[] { HydrogenGas, NitrogenGas, OxygenGas }, 21);
        addInput(LargeChemicalReactor, SulfuricAcid, new Object[] { SulfurDust, OxygenGas, Water }, 7);
        addInput(ChemicalPlant, Nitrobenzene, new Object[] { Benzene, SulfuricAcid, NitricAcid, DistilledWater }, 12);
        addInput(DistillationTower, DistilledWater, Water, -1);
        addInput(ChemicalPlant, FermentationBase, new Object[] { Fruit, DistilledWater }, 2);
        addInput(ChemicalPlant, HydrogenPeroxide, new Object[] { OxygenGas, Ethylanthrahydroquinone, Anthracene }, 4);
        addInput(ChemicalPlant, Ethylanthrahydroquinone, new Object[] { Ethylanthraquinone, HydrogenGas, OrangeMetalCatalyst }, 4);
        addInput(VacuumFreezer, LiquidNitrogen, NitrogenGas, -1);
        addInput(LargeChemicalReactor, SodiumNitrateDust, new Object[] { SodiumDust, NitricAcid }, -1);
        addInput(LargeChemicalReactor, PotassiumNitrateDust, new Object[] { PotassiumDust, NitricAcid }, 2);
        addInput(MixerNonCell, SaltWater, new Object[] { SodiumChlorideDust, Water }, 3);
        addInput(LargeChemicalReactor, SodiumHydroxideDust, new Object[] { SodiumDust, Water }, 1);
        addInput(LargeChemicalReactor, CarbonMonoxideGas, new Object[] { CarbonDust, OxygenGas }, 1);
        addInput(LargeChemicalReactor, NickelTetracarbonyl, new Object[] { NickelDust, CarbonMonoxideGas }, -1);
        addInput(LargeChemicalReactor, MethaneGas, new Object[] { CarbonDust, HydrogenGas }, 1);
        addInput(LargeChemicalReactor, Methanol, new Object[] { CarbonDust, HydrogenGas, OxygenGas }, 23);
        addInput(LargeChemicalReactor, SodiumFormateFluid, new Object[] { SodiumHydroxideDust, CarbonMonoxideGas }, -1);
        addInput(LargeChemicalReactor, FormicAcid, new Object[] { SodiumFormateFluid, SulfuricAcid }, 1);
        addInput(LargeChemicalReactor, PotassiumDisulfateDust, new Object[] { PotassiumDust, SulfurDust, OxygenGas }, -1);
        addInput(FluidExtractor, PotassiumDisulfateMolten, PotassiumDisulfateDust, -1);
        addInput(LargeChemicalReactor, SodiumChlorideDust, new Object[] { SodiumHydroxideDust, HydrochloricAcid }, 1);
        addInput(LargeChemicalReactor, Acetone, new Object[] { AceticAcid, CalciumDust }, 3);
        addInput(LargeChemicalReactor, AceticAcid, new Object[] { CarbonMonoxideGas, HydrogenGas }, 24);
        addInput(LargeChemicalReactor, AmmoniumNitrateSolution, new Object[] { NitricAcid, AmmoniaGas }, 12);
        addInput(ChemicalDehydratorNonCell, AmmoniumNitrateDust, HydratedAmmoniumNitrateSlurry, 8);
        addInput(ChemicalPlant, HydratedAmmoniumNitrateSlurry, new Object[] { NitricAcid, AmmoniaGas }, 21);
        addInput(LargeChemicalReactor, OxalicAcid, new Object[] { SugarDust, NitricAcid, VanadiumPentoxideDust }, 1);
        addInput(LargeChemicalReactor, SodiumFluorosilicate, new Object[] { SodiumChlorideDust, HexafluorosilicicAcid }, -1);
        addInput(LargeChemicalReactor, HexafluorosilicicAcid, new Object[] { SiliconDust, HydrofluoricAcid }, -1);
        addInput(LargeChemicalReactor, CarbonDioxideGas, new Object[] { CarbonDust, OxygenGas }, 2);
        addInput(LargeChemicalReactor, QuicklimeDust, new Object[] { CalciumDust, OxygenGas }, 1);
        addInput(LargeChemicalReactor, CalciteDust, new Object[] { CalciumDust, CarbonDust, OxygenGas }, -1);
        addInput(LargeChemicalReactor, PhosphoricAcid, new Object[] { PhosphorusDust, OxygenGas, Water }, 24);

        // Kevlar calcium supply: calcium -> hydride -> blast-furnace disilicide; chloride choice is route-local.
        addInput(BlastFurnace, CalciumDisilicideDust, new Object[] { CalciumHydrideDust, SiliconDust }, -1);
        addInput(LargeChemicalReactor, CalciumHydrideDust, new Object[] { CalciumDust, HydrogenGas }, 1);

        // Organorhodium catalyst: rhodium chloride, phosphine and borohydride, then their native upstream paths.
        addInput(LargeChemicalReactor, OrganorhodiumCatalystDust,
            new Object[] { RhodiumIIIChlorideDust, TriphenylphosphineDust, SodiumBorohydrideDust, CarbonMonoxideGas }, 1);
        addInput(BlastFurnace, RhodiumIIIChlorideDust, new Object[] { RhodiumDust, ChlorineGas }, 2);
        addInput(LargeChemicalReactor, TriphenylphosphineDust,
            new Object[] { SodiumDust, PhosphorusTrichloride, Chlorobenzene }, 1);
        addInput(LargeChemicalReactor, PhosphorusTrichloride, new Object[] { PhosphorusDust, ChlorineGas }, 1);
        addInput(LargeChemicalReactor, Chlorobenzene, new Object[] { Benzene, ChlorineGas }, 1);
        addInput(LargeChemicalReactor, SodiumBorohydrideDust, new Object[] { SodiumHydrideDust, TrimethylBorate }, 1);
        addInput(LargeChemicalReactor, SodiumHydrideDust, new Object[] { SodiumDust, HydrogenGas }, 2);
        addInput(LargeChemicalReactor, TrimethylBorate, new Object[] { Methanol, BoricAcid, SulfuricAcid }, 1);
        addInput(LargeChemicalReactor, BoricAcid, new Object[] { BoraxDust, HydrochloricAcid }, 1);

        // Purification consumables: returned phosphoric acid, sodium hydroxide and waste reagents cancel first.
        addInput(Assembler, ActivatedCarbonFilterMesh, new Object[] { ActivatedCarbonDust, ZincFoil }, -1);
        addInput(Bender, ZincFoil, ZincIngot, 10);
        addInput(Furnace, ZincIngot, ZincDust, -1);
        addInput(ChemicalBath, ActivatedCarbonDust, new Object[] { DirtyActivatedCarbonDust, Water }, -1);
        addInput(BlastFurnace, DirtyActivatedCarbonDust, PreActivatedCarbonDust, -1);
        addInput(LargeChemicalReactor, PreActivatedCarbonDust, new Object[] { CarbonDust, PhosphoricAcid }, -1);
        addInput(LaserEngraver, OzoneGas, new Object[] { Air, BlueTopazLens }, -1);
        addInput(LargeChemicalReactor, PolyAluminiumChloride, new Object[] { AluminiumHydroxideDust, HydrochloricAcid }, -1);
        addInput(LargeChemicalReactor, AluminiumHydroxideDust, new Object[] { SodiumAluminateDust, Water }, 1);
        addInput(LargeChemicalReactor, SodiumAluminateDust, new Object[] { AluminiumDust, SodiumHydroxideDust, Water }, 24);
        addInput(MixerNonCell, SuperCoolant, new Object[] { CallistoIceDust, LedoxDust, IC2Coolant }, -1);
        addInput(MixerNonCell, IC2Coolant, new Object[] { LapisDust, DistilledWater }, 4);

        // Crystalline alloy: melt <- cooled ingot <- xenon blast <- mixer; crystals use the autoclave path.
        if (Mods.EnderIO.isModLoaded() && PulsatingCrystal != null && PulsatingCrystalDust != null) {
            addInput(FluidExtractor, CrystallineAlloyMolten, CrystallineAlloyIngot, -1);
            addInput(VacuumFreezer, CrystallineAlloyIngot, HotCrystallineAlloyIngot, -1);
            addInput(BlastFurnace, HotCrystallineAlloyIngot, new Object[] { CrystallineAlloyDust, XenonGas }, 11);
            addInput(MixerNonCell, CrystallineAlloyDust, new Object[] { PulsatingCrystalDust, GoldDust, EmeraldDust }, 2);
            addInput(Macerator, PulsatingCrystalDust, PulsatingCrystal, -1);
            addInput(Autoclave, PulsatingCrystal, new Object[] { DiamondGem, PulsatingIronMolten }, -1);
            addInput(FluidExtractor, PulsatingIronMolten, PulsatingIronIngot, -1);
            addInput(BlastFurnace, PulsatingIronIngot, new Object[] { PulsatingIronDust, OxygenGas }, 11);
            addInput(MixerNonCell, PulsatingIronDust, new Object[] { IronDust, EnderPearlDust, RedstoneAlloyDust }, 2);
            addInput(Macerator, EnderPearlDust, EnderPearl, -1);
            addInput(MixerNonCell, RedstoneAlloyDust, new Object[] { RedstoneDust, SiliconDust, CoalDust }, 2);
        }

        // Output paths: recover reusable acids and follow other coproducts to their recorded final materials.
        addOutput(DistillationTower, FlocculationWasteLiquid, new Object[] { AluminiumDust, OxygenGas, HydrochloricAcid }, -1);
        addOutput(LargeChemicalReactor, NitrogenMonoxideGas,
            new Object[] { NitrogenMonoxideGas, OxygenGas }, NitrogenDioxideGas, 9);
        addOutput(LargeChemicalReactor, NitrogenDioxideGas,
            new Object[] { NitrogenDioxideGas, OxygenGas, Water }, NitricAcid, 24);
        addOutput(LargeChemicalReactor, SulfurDioxideGas,
            new Object[] { SulfurDioxideGas, OxygenGas, Water }, SulfuricAcid, 9);
        addOutput(LargeChemicalReactor, SulfurTrioxideGas,
            new Object[] { SulfurTrioxideGas, Water }, SulfuricAcid, 9);
        addOutput(LargeChemicalReactor, DilutedSulfuricAcid, new Object[] { DilutedSulfuricAcid, SulfurDust, OxygenGas }, SulfuricAcid, 23);
        addOutput(FluidHeater, DilutedAcetone, Acetone, -1);
        addOutput(ElectrolyzerNonCell, CarbonMonoxideGas, CarbonDust, 1);
        addOutput(ElectrolyzerNonCell, CarbonDioxideGas, CarbonDust, 1);
        addOutput(FluidSolidifier, CalciumFluorideFluid, CalciumFluorideDust, 1);
        addOutput(ElectrolyzerNonCell, CalciumFluorideDust, CalciumDust, -1);
        addOutput(ElectrolyzerNonCell, FluorsparDust, CalciumDust, -1);
        addOutput(ElectrolyzerNonCell, AdamantiumOxideDust, AdamantiumDust, -1);
        addOutput(ElectrolyzerNonCell, SodiumHydroxideDust, SodiumDust, -1);
        addOutput(LargeChemicalReactor, SodiumMethoxideDust, new Object[] { SodiumMethoxideDust, Water },
            new Object[] { SodiumHydroxideDust, Methanol }, 1);
        addOutput(CentrifugeNonCell, TricalciumPhosphateDust, new Object[] { CalciumDust, PhosphateDust }, -1);
        addOutput(ElectrolyzerNonCell, PhosphateDust, PhosphorusDust, -1);
        addOutput(ElectrolyzerNonCell, BariumSulfateDust, BariumDust, -1);
        addOutput(ElectrolyzerNonCell, QuicklimeDust, CalciumDust, -1);
        addOutput(ElectrolyzerNonCell, Phenol, CarbonDust, -1);
        addOutput(LargeChemicalReactor, SodiumSulfateDust, SodiumDust, -1);
        addOutput(FluidSolidifier, PotassiumMolten, PotassiumIngot, -1);
        addOutput(Macerator, PotassiumIngot, PotassiumDust, -1);
        addOutput(ElectrolyzerNonCell, CalciumChlorideDust, CalciumDust, -1);
        addOutput(ElectrolyzerNonCell, CalciumChlorideFluid, CalciumDust, -1);
        addOutput(LargeChemicalReactor, MagnesiumChlorideDust,
            new Object[] { MagnesiumChlorideDust, SodiumDust }, new Object[] { MagnesiumDust, SodiumChlorideDust }, -1);
        addOutput(ElectrolyzerNonCell, ZincSulfateDust, ZincDust, -1);
        addOutput(ElectrolyzerNonCell, EthyleneGas, CarbonDust, -1);
        addOutput(ElectrolyzerNonCell, SodiumChlorideDust, SodiumDust, -1);
        addOutput(ElectrolyzerNonCell, AmmoniaGas, NitrogenGas, -1);
        addOutput(ElectrolyzerNonCell, ChloromethaneGas, CarbonDust, -1);
        // spotless:on
    }

    public static ReagentStep getInputSynthesis(Object target) {
        return INPUT_SYNTHESES.get(target);
    }

    public static ReagentStep getOutputDecomposition(Object target) {
        return OUTPUT_DECOMPOSITIONS.get(target);
    }

    private static void addInput(RecipeMap<?> pool, Object target, Object inputs, int circuit) {
        INPUT_SYNTHESES.put(target, new ReagentStep(pool, inputs, target, circuit));
    }

    private static void addOutput(RecipeMap<?> pool, Object target, Object outputs, int circuit) {
        addOutput(pool, target, target, outputs, circuit);
    }

    private static void addOutput(RecipeMap<?> pool, Object target, Object inputs, Object outputs, int circuit) {
        OUTPUT_DECOMPOSITIONS.put(target, new ReagentStep(pool, inputs, outputs, circuit));
    }

    /** One source-recipe marker in a material path; quantities and duration are resolved during cache loading. */
    @Desugar
    public record ReagentStep(RecipeMap<?> pool, Object inputs, Object outputs, int circuit) {}
}
